const photos = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const questions = [["Q1", "Who is your favourite sibling? 👀", ["Me, obviously 😌", "I need to think 😂", "Someone else 😒"]], ["Q2", "What is your favourite memory with me? 🥹", null], ["Q3", "Who annoys whom more? 😂", ["You annoy me 😌", "I annoy you 😂", "Both of us equally 🤝"]], ["Q4", "If you could ask me for one birthday gift, what would it be? 🎁", null], ["Q5", "Describe our bond in one word. 💕", null]];
const personalMessage = "Heyy Shabrin… 🫂❤️\n\nThu mera life ma bahuth important person thera. Thera place konbi replace karna hongani. 🫂❤️\n\nHamara andhar fights aangani, vaisach kiyathibi aayathobi… my kabubi rangi thera saath thu bi rangi maalam. ❤️🫂\n\nMera life ma last ending thalak thu mera saath ranna karko yaath karthu. ❤️🫂\n\nKabubi my thuja konsa situation ma bi chodko dhengini. I will always be there for you… 😘🫂\n\nLove you so much, Shabrin! 🫂❤️\n\nHappy Birthday Shabrin! 🦢🌸🎂💗";

let current = 0;
let answers = [];
let selectedAnswer = '';

function showPage(id){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  window.scrollTo({top:0,behavior:'smooth'});
}

function startQuiz(){
  current=0;
  answers=[];
  selectedAnswer='';
  showPage('quiz');
  renderQuestion();
}

function renderQuestion(){
  const q=questions[current];
  selectedAnswer = answers[current] || '';
  document.getElementById('counter').textContent=`Question ${current+1} of ${questions.length}`;
  document.getElementById('bar').style.width=((current+1)/questions.length*100)+'%';
  let html=`<div class="question">${q[1]}</div>`;

  if(q[2]){
    html+=`<div class="answers">${q[2].map(a=>`<button type="button" class="answer ${selectedAnswer===a?'selected':''}" onclick="chooseAnswer(${JSON.stringify(a)})">${a}</button>`).join('')}</div>`;
    html+=`<button id="nextBtn" class="btn" style="margin-top:18px;opacity:${selectedAnswer?'1':'.5'}" onclick="nextQuestion()" ${selectedAnswer?'':'disabled'}>${current===questions.length-1?'Finish Questions 💌':'Next 💗'}</button>`;
  }else{
    html+=`<textarea id="freeAnswer" placeholder="Type your answer here… 💕">${selectedAnswer}</textarea>
           <button id="nextBtn" class="btn" style="margin-top:16px;opacity:${selectedAnswer?'1':'.5'}" onclick="saveFreeAnswer()" ${selectedAnswer?'':'disabled'}>${current===questions.length-1?'Finish Questions 💌':'Next 💗'}</button>`;
  }
  if(current>0) html+=`<button type="button" class="backBtn" onclick="previousQuestion()">← Previous</button>`;
  document.getElementById('questionArea').innerHTML=html;

  const input=document.getElementById('freeAnswer');
  if(input){
    input.addEventListener('input',()=>{
      const ok=input.value.trim().length>0;
      const btn=document.getElementById('nextBtn');
      btn.disabled=!ok; btn.style.opacity=ok?'1':'.5';
    });
  }
}

function chooseAnswer(a){
  selectedAnswer=a;
  document.querySelectorAll('.answer').forEach(btn=>btn.classList.toggle('selected',btn.textContent===a));
  const btn=document.getElementById('nextBtn');
  btn.disabled=false; btn.style.opacity='1';
}

function saveFreeAnswer(){
  const v=document.getElementById('freeAnswer').value.trim();
  if(!v) return;
  answers[current]=v;
  nextQuestion();
}

function nextQuestion(){
  if(questions[current][2] && !selectedAnswer) return;
  if(questions[current][2]) answers[current]=selectedAnswer;
  current++;
  selectedAnswer = answers[current] || '';
  if(current<questions.length){
    renderQuestion();
  }else{
    renderAnswers();
    showPage('answersReview');
  }
}

function previousQuestion(){
  if(current>0){
    current--;
    selectedAnswer=answers[current] || '';
    renderQuestion();
  }
}

function renderAnswers(){
  document.getElementById('answersList').innerHTML=questions.map((q,i)=>`
    <div style="padding:15px 0;border-bottom:1px solid #f0d9e7;text-align:left">
      <div style="font-weight:700;margin-bottom:7px">${i+1}. ${q[1]}</div>
      <div style="color:#7b526a">💗 ${answers[i] || 'No answer'}</div>
    </div>`).join('');
}
document.getElementById('gallery').innerHTML=photos.map((p,i)=>`<img src="${p}" alt="Memory ${i+1}" loading="lazy">`).join('');
document.getElementById('messageText').textContent=personalMessage;

function showFinal(){
  showPage('final');
  for(let i=0;i<90;i++){
    const c=document.createElement('div');
    c.className='confetti';
    c.style.left=Math.random()*100+'vw';
    c.style.animationDelay=(Math.random()*1.2)+'s';
    c.style.transform=`rotate(${Math.random()*360}deg)`;
    c.style.background=['#e77eaa','#9d84df','#f5c7d9','#b8a1e8','#f7d98b'][Math.floor(Math.random()*5)];
    document.body.appendChild(c);
    setTimeout(()=>c.remove(),4200);
  }
}
